context_info = ()
for d in context:
    prompt = "You will be given one document. Extract any information relevant to the following very specific query. Provide concise bullet points with direct quotes and page/line references if available. If nothing relevant is present, reply with 'No relevant info'.\n\nQUERY DETAILS:\nWe are looking for an Asian singer who:\n- Released their debut single in 2011.\n- Has the Chinese zodiac sign Dragon.\n- Debuted as a member of a group before 2018.\n- Shortly after their group debut (and before 2018), performed at a showcase in a country different from their origin.\n- At that showcase, performed a covered version of a song that fits: the song was originally released by an artist in a different country, then was covered and released by a different artist in another country with the language of the lyrics changed.\n- This showcase performance led to the singer receiving a nickname that shares one word with the song title performed.\n\nFrom the document, extract any of the following if present:\n- Singer name, nationality/origin, birth year (or Chinese zodiac explicitly), group name, group debut date.\n- Singer’s solo debut single title and year (specifically note if it is 2011).\n- Chinese zodiac; explicitly note if Dragon.\n- Showcase details: date/year (confirm before 2018), country (confirm it is different from singer’s origin), setlist or song performed.\n- The covered song details: title; original artist and country; cover artist and country; what language changed between the original and the cover; release info of the cover.\n- The nickname given to the singer because of this performance; explicitly check if the nickname shares one word with the song title; provide the exact nickname text as quoted.\n\nFormat your output as:\nDocument findings:\n- Singer(s): ...\n- Debut single/year: ...\n- Chinese zodiac: ...\n- Group and debut info: ...\n- Showcase details: ...\n- Covered song provenance and language change: ...\n- Nickname (exact text) and why given: ...\n- Quotes: ...\n\nDocument:\nBEGIN\n" + d + "\nEND"
    result = llm_query(prompt)
    context_info = context_info + (result,)

compiled = ""
for r in context_info:
    compiled = compiled + r + "\n\n"

final_query = "You are given extracted findings from multiple documents. Determine the single best-supported answer to the following question and output ONLY the nickname (no quotes, no extra words):\n\nQuestion:\nThere is a song originally released by an artist in one country that was later covered and released by a different artist in a different country with a language change. An Asian singer performed this covered version at a showcase in a country different from their origin shortly after their group debut (before 2018). This performance led to a nickname for the singer that shares one word with the song title. The singer released their debut single in 2011 and has a Dragon Chinese zodiac. What is the nickname the singer was called after their performance?\n\nContexted extractions:\n" + compiled + "\n\nInstructions:\n- Cross-check all constraints: 2011 solo debut single; Dragon zodiac; group debut before 2018; showcase abroad; performance of the covered, language-changed song; nickname stems from that performance and shares a word with the song title.\n- If multiple candidates, choose the one matching all constraints with explicit evidence in the extractions. If the nickname appears in quotes, remove quotes for the final output.\n- Output ONLY the nickname as a single line."

answer = llm_query(final_query)
return_result(answer.strip())